package com.costeo3d.infrastructure.persistence.dao;

import java.util.List;
import java.util.Optional;

import com.costeo3d.domain.model.Customer;

/** Persistence contract for the customer catalogue. */
public interface CustomerDao {

    // Returns a new instance with the ID generated by MySQL.
    Customer insert(Customer customer);

    Optional<Customer> findById(int id);

    // Includes active and inactive customers.
    List<Customer> findAll();

    // Returns false if no customer exists with the given ID.
    boolean update(Customer customer);
}
